const THREE_MODULE_URL =
  "./vendor/three-0.184.0/three.module.min.js";
const SATELLITE_SGP4_MODULE_URL =
  "./vendor/satellite-js-7.1.0.esm.js";
// Kick off the heavy 3D runtime download the moment this module evaluates so it
// streams in parallel with parsing, the initial data fetches, and scene setup
// rather than only starting once bootstrap() reaches its await. bootstrap()
// re-awaits this promise (handling any load failure there); the noop catch just
// keeps a module failure from surfacing as an unhandled rejection before then.
const THREE_MODULE = import(THREE_MODULE_URL);
THREE_MODULE.then(
  () => WORLD_BOOT?.mark("three", "three.js r184 module ready", "module"),
  () => {},
);
// The scene builder cannot run before three.js resolves, so it does not belong
// in the shell's static graph: the first visit would parse a megabyte of
// geometry before the loading curtain could paint. world-loader.js
// modulepreloads it (and three.js) after its first frame, so this import is
// served from that preload rather than opening a new request, and it streams
// beside the same-origin three.js fetch that bootstrap() has to wait for anyway.
const WORLD_SCENE_MODULE = import("./world-scene.js");
WORLD_SCENE_MODULE.then(
  () => WORLD_BOOT?.mark("scene-module", "world-scene.js module ready", "module"),
  () => {},
);
let satelliteSgp4ModulePromise = null;

function loadSatelliteSgp4Module() {
  if (!satelliteSgp4ModulePromise) {
    satelliteSgp4ModulePromise = import(SATELLITE_SGP4_MODULE_URL).then(
      (module) => {
        if (
          typeof module?.json2satrec !== "function" ||
          typeof module?.sgp4 !== "function"
        ) {
          throw new TypeError("The local satellite SGP4 module is invalid");
        }
        return Object.freeze({
          json2satrec: module.json2satrec,
          sgp4: module.sgp4,
        });
      },
    );
  }
  return satelliteSgp4ModulePromise;
}
