function worldAgentRepository(value) {
  const match = String(value || "")
    .trim()
    .match(/^([a-z](?:[a-z0-9-]{0,61}[a-z0-9])?)\/([A-Za-z0-9._-]{1,100})$/i);
  if (!match) return null;
  const owner = match[1].toLowerCase();
  return { owner, name: match[2], display: `${owner}/${match[2]}` };
}

function worldAgentRepositoryChoices(values, limit = 12) {
  const seen = new Set();
  const choices = [];
  for (const value of Array.isArray(values) ? values : []) {
    const repo = worldAgentRepository(value);
    if (!repo || seen.has(repo.display.toLowerCase())) continue;
    seen.add(repo.display.toLowerCase());
    choices.push(repo);
    if (choices.length >= limit) break;
  }
  return choices;
}

function worldAgentSessionsPath(repo) {
  return `/api/repo/${encodeURIComponent(repo.owner)}/${encodeURIComponent(
    repo.name,
  )}/agent-sessions`;
}

function worldAgentTargetKind(target) {
  return WORLD_AGENT_RUNNER_RUNTIMES.has(
    String(target?.runtimeMode || "").toLowerCase(),
  )
    ? "runner"
    : "desktop";
}

function worldAgentTargetFor(targets, kind) {
  return (
    (Array.isArray(targets) ? targets : [])
      .filter(
        (target) =>
          target &&
          typeof target.node === "string" &&
          target.node &&
          Array.isArray(target.providers) &&
          target.providers.length > 0 &&
          worldAgentTargetKind(target) === kind,
      )
      .sort(
        (left, right) =>
          Number(Boolean(right.online)) - Number(Boolean(left.online)),
      )[0] || null
  );
}

const WORLD_RUNNERS_PAGE = "/dashboard/runners";
const WORLD_RUNNERS_SETUP_PAGE = "/dashboard/runners?setup=1";
const WORLD_RUNNER_ATTENTION_PATH = "/api/runners/attention";
const WORLD_RUNNER_ATTENTION_POLL_MS = 5 * 60 * 1000;
const WORLD_RUNNER_ATTENTION_FIRST_MS = 4000;
const WORLD_RUNNER_PROVIDERS = Object.freeze(["claude-code", "codex"]);
const WORLD_RUNNER_NAME = /^[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?$/;

function worldRunnerConnectHref(runner, provider) {
  return `${WORLD_RUNNERS_PAGE}?runner=${encodeURIComponent(
    runner,
  )}&provider=${encodeURIComponent(provider)}&connect=1`;
}

function worldRelativeAge(ms, now = Date.now()) {
  const value = Number(ms) || 0;
  if (!value) return "never";
  const seconds = Math.max(0, Math.round((now - value) / 1000));
  if (seconds < 90) return "just now";
  const minutes = Math.round(seconds / 60);
  if (minutes < 90) return `${minutes} min ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 48) return `${hours} h ago`;
  return `${Math.round(hours / 24)} days ago`;
}

function worldAgentProviderLabel(provider) {
  return WORLD_AGENT_PROVIDER_LABELS[provider] || String(provider || "");
}

function worldAgentRunnerStatuses(targets) {
  const seen = new Map();
  for (const target of Array.isArray(targets) ? targets : []) {
    if (!target || worldAgentTargetKind(target) !== "runner") continue;
    const list =
      Array.isArray(target.runners) && target.runners.length
        ? target.runners
        : [
            {
              name: String(target.runner || target.node || ""),
              online: Boolean(target.online),
              lastSeenAt: Number(target.lastSeenAt) || 0,
              ready: Array.isArray(target.providers) ? target.providers : [],
              needsLogin: Object.keys(target.needsLogin || {}),
              signIn: [],
            },
          ];
    for (const status of list) {
      const name = String(status?.name || "").toLowerCase();
      if (!WORLD_RUNNER_NAME.test(name) || seen.has(name)) continue;
      seen.set(name, {
        name,
        online: Boolean(status.online),
        lastSeenAt: Number(status.lastSeenAt) || 0,
        ready: Array.isArray(status.ready) ? status.ready : [],
        needsLogin: Array.isArray(status.needsLogin) ? status.needsLogin : [],
        signIn: Array.isArray(status.signIn) ? status.signIn : [],
      });
    }
  }
  return Array.from(seen.values());
}

function worldAgentRunnerNotice(targets, repoDisplay, now = Date.now()) {
  const usable = worldAgentTargetFor(targets, "runner");
  if (usable?.online) return null;
  if (usable) {
    const name = String(usable.runner || usable.node);
    return {
      text: `${name} is offline, last seen ${worldRelativeAge(
        usable.lastSeenAt,
        now,
      )}. The prompt waits until it reconnects.`,
      tone: "muted",
      action: { label: "Runners", panel: true },
    };
  }
  const statuses = worldAgentRunnerStatuses(targets);
  const seen = (status) =>
    status.online
      ? ""
      : ` It is offline, last seen ${worldRelativeAge(status.lastSeenAt, now)}.`;
  const expired = statuses.find((status) => status.needsLogin.length);
  if (expired) {
    const provider = expired.needsLogin[0];
    const label = worldAgentProviderLabel(provider);
    return {
      text: `${expired.name} needs ${label} reconnected.${seen(expired)}`,
      tone: "bad",
      action: {
        label: `Connect ${label}`,
        href: worldRunnerConnectHref(expired.name, provider),
      },
    };
  }
  const unsigned = statuses.find((status) => status.signIn.length);
  if (unsigned) {
    const provider = unsigned.signIn[0];
    const label = worldAgentProviderLabel(provider);
    return {
      text: `${unsigned.name} needs ${label} signed in.${seen(unsigned)}`,
      tone: "bad",
      action: {
        label: `Connect ${label}`,
        href: worldRunnerConnectHref(unsigned.name, provider),
      },
    };
  }
  if (statuses.length) {
    return {
      text: `${statuses[0].name} has no agent CLI installed yet.${seen(
        statuses[0],
      )}`,
      tone: "bad",
      action: { label: "Manage", href: WORLD_RUNNERS_PAGE },
    };
  }
  return {
    text: `No runner yet for ${repoDisplay || "this repository"} —`,
    tone: "bad",
    action: { label: "Set one up", href: WORLD_RUNNERS_SETUP_PAGE },
  };
}

function worldRunnerProviderState(entry, now = Date.now()) {
  if (!entry || typeof entry !== "object") {
    return { state: "unknown", text: "Not reported", connect: false };
  }
  if (entry.binaryFound === false) {
    return { state: "missing", text: "Not installed", connect: false };
  }
  const auth =
    entry.loginState === "expired"
      ? "expired"
      : String(entry.auth?.state || "");
  if (auth === "expired") {
    return { state: "expired", text: "Needs sign-in", connect: true };
  }
  if (entry.loginState === "available") {
    if (auth === "expiring") {
      const left = (Number(entry.auth?.expiresAt) || 0) - now;
      return {
        state: "expiring",
        text:
          left > 0
            ? `Signed in · expires in ${Math.max(1, Math.round(left / 3600000))} h`
            : "Signed in · expires soon",
        connect: true,
      };
    }
    return { state: "ok", text: "Signed in", connect: false };
  }
  return { state: "signin", text: "Needs sign-in", connect: true };
}

function worldRunnerRows(runners, targets, now = Date.now()) {
  const rows = new Map();
  for (const runner of Array.isArray(runners) ? runners : []) {
    const name = String(runner?.name || "").toLowerCase();
    if (!WORLD_RUNNER_NAME.test(name) || runner.status === "revoked") continue;
    const lastSeenAt = Number(runner.lastSeenAt) || 0;
    rows.set(name, {
      name,
      scope: String(runner.scope || ""),
      manage: true,
      online: Boolean(lastSeenAt && now - lastSeenAt <= 10 * 60 * 1000),
      lastSeenAt,
      jobs: Math.max(0, Number(runner.activeLeases) || 0),
      providers: WORLD_RUNNER_PROVIDERS.map((provider) => ({
        provider,
        label: worldAgentProviderLabel(provider),
        ...worldRunnerProviderState(runner.availability?.[provider], now),
      })),
    });
  }
  for (const status of worldAgentRunnerStatuses(targets)) {
    if (rows.has(status.name)) continue;
    rows.set(status.name, {
      name: status.name,
      scope: "",
      manage: false,
      online: status.online,
      lastSeenAt: status.lastSeenAt,
      jobs: 0,
      providers: WORLD_RUNNER_PROVIDERS.map((provider) => {
        const label = worldAgentProviderLabel(provider);
        if (status.ready.includes(provider)) {
          return { provider, label, state: "ok", text: "Signed in", connect: false };
        }
        if (status.needsLogin.includes(provider) || status.signIn.includes(provider)) {
          return { provider, label, state: "expired", text: "Needs sign-in", connect: false };
        }
        return { provider, label, state: "missing", text: "Not installed", connect: false };
      }),
    });
  }
  return Array.from(rows.values()).sort(
    (left, right) =>
      Number(right.online) - Number(left.online) ||
      left.name.localeCompare(right.name),
  );
}

function worldRunnerAttentionSummary(payload) {
  const items = (Array.isArray(payload?.items) ? payload.items : []).filter(
    (item) =>
      item &&
      WORLD_RUNNER_NAME.test(String(item.runner || "")) &&
      WORLD_RUNNER_PROVIDERS.includes(item.provider),
  );
  if (!items.length) return null;
  const first = items[0];
  const label = worldAgentProviderLabel(first.provider);
  const text =
    first.state === "expired"
      ? `${first.runner} needs ${label} sign-in`
      : `${first.runner}: ${label} sign-in expires soon`;
  const href = String(first.connectUrl || "").startsWith(`${WORLD_RUNNERS_PAGE}?`)
    ? String(first.connectUrl)
    : worldRunnerConnectHref(first.runner, first.provider);
  return {
    text: items.length > 1 ? `${text} · +${items.length - 1}` : text,
    state: items.some((item) => item.state === "expired") ? "expired" : "expiring",
    href,
    count: items.length,
  };
}

function worldAgentModelOptions(models, target) {
  const catalog =
    models && typeof models === "object" ? models : WORLD_AGENT_FALLBACK_MODELS;
  const providers =
    Array.isArray(target?.providers) && target.providers.length
      ? target.providers
      : Object.keys(WORLD_AGENT_FALLBACK_MODELS);
  const options = [];
  for (const provider of providers) {
    const aliases = Array.isArray(catalog[provider]) ? catalog[provider] : [];
    for (const alias of aliases) {
      const model = String(alias || "");
      if (!model) continue;
      const value = `${provider}:${model}`;
      options.push({
        value,
        provider: String(provider),
        model,
        label: WORLD_AGENT_MODEL_LABELS[value] || model,
      });
    }
  }
  return options;
}

function worldAgentPickModel(options, remembered) {
  const list = Array.isArray(options) ? options : [];
  if (list.some((option) => option.value === remembered)) return remembered;
  return (
    (
      list.find((option) => option.value === WORLD_AGENT_DEFAULT_MODEL) ||
      list[0]
    )?.value || ""
  );
}

function worldAgentRunState(status, fallback = "") {
  const value = String(status || "").toLowerCase();
  if (value === "running") return "running";
  if (value === "completed") return "done";
  if (value === "failed" || value === "rejected") return "failed";
  if (fallback === "waiting_for_desktop" || fallback === "waiting") {
    return "waiting";
  }
  return "queued";
}

function worldAgentRunCopy(run) {
  const node = String(run?.node || "the node");
  switch (run?.state) {
    case "waiting":
      return `Queued · starts when ${node} reconnects`;
    case "running":
      return `Running on ${node}`;
    case "done":
      return `Finished on ${node}`;
    case "failed":
      return `Failed on ${node}`;
    default:
      return `Queued on ${node}`;
  }
}

const WORLD_CHAT_CHANNEL_KEY = "forkmesh.world.chatChannel.v1";
const WORLD_CHAT_PRIVATE_CHANNEL_KEY = "forkmesh.chat.channel";
const WORLD_CHAT_PRIVATE_DIRECT_KEY = "forkmesh.chat.direct";
const WORLD_CHAT_CHOICES_TTL_MS = 60 * 1000;
const WORLD_CHAT_PRIVATE_LIMIT = 12;
const WORLD_CHAT_SPACES = Object.freeze([
  Object.freeze({ space: "", channel: "#general" }),
]);
const WORLD_CHAT_SPACE_RE = /^[a-z][a-z-]{0,39}$/;

function worldChatSpaceChoices(spaces, signedIn) {
  const source =
    Array.isArray(spaces) && spaces.length ? spaces : WORLD_CHAT_SPACES;
  const seen = new Set();
  const choices = [];
  for (const entry of source) {
    const space = String(entry?.space || "");
    const channel = String(entry?.channel || "");
    if (seen.has(space) || (space && !WORLD_CHAT_SPACE_RE.test(space))) {
      continue;
    }
    if (!/^#[a-z0-9-]{1,60}$/.test(channel)) continue;
    if (space && !signedIn) continue;
    seen.add(space);
    choices.push({
      id: `space:${space}`,
      kind: "space",
      space,
      label: channel,
    });
  }
  return choices;
}

function worldChatPrivateChoices(channels, directs) {
  const rooms = (Array.isArray(channels) ? channels : [])
    .filter(
      (channel) =>
        /^[0-9a-f]{32}$/.test(String(channel?.id || "")) &&
        String(channel?.name || "").trim() &&
        channel?.readOnly !== true,
    )
    .slice(0, WORLD_CHAT_PRIVATE_LIMIT)
    .map((channel) => ({
      id: `channel:${channel.id}`,
      kind: "channel",
      roomId: String(channel.id),
      label: `#${String(channel.name).trim().replace(/^#+/, "").slice(0, 60)}`,
      visibility: String(channel.visibility || ""),
    }));
  const people = (Array.isArray(directs) ? directs : [])
    .filter(
      (direct) =>
        /^[0-9a-f]{32}$/.test(String(direct?.id || "")) &&
        /^[a-z][a-z0-9-]{0,62}$/.test(String(direct?.otherUser || "")),
    )
    .slice(0, WORLD_CHAT_PRIVATE_LIMIT)
    .map((direct) => ({
      id: `dm:${direct.id}`,
      kind: "dm",
      roomId: String(direct.id),
      label: `@${direct.otherUser}`,
      unread: Math.max(0, Number(direct.unreadCount) || 0),
    }));
  return { channels: rooms, directs: people };
}

function worldChatPickSpace(choices, remembered) {
  const list = Array.isArray(choices) ? choices : [];
  const wanted = `space:${String(remembered || "")}`;
  return (list.find((choice) => choice.id === wanted) || list[0] || null)
    ?.space ?? "";
}

function orgAgentSavedMessage(payload) {
  const serverMessage = String(payload?.message || "").trim();
  if (serverMessage) return serverMessage;
  const target = String(
    payload?.targetNode ||
      payload?.session?.targetNode ||
      "the linked desktop",
  );
  const waitingForDesktop =
    payload?.targetOnline === false ||
    payload?.queueState === "waiting_for_desktop";
  return waitingForDesktop
    ? `Saved for ${target}. It will start after the linked desktop reconnects and passes the Haiku safety check.`
    : `Saved for ${target}. It will start after the Haiku safety check passes.`;
}
