function worldNoticeHostKey(element) {
  if (!(element instanceof Element)) return "";
  const escape = (value) =>
    typeof CSS !== "undefined" && typeof CSS.escape === "function"
      ? CSS.escape(value)
      : String(value).replace(/["\\]/g, "\\$&");
  let key = "";
  if (element.id) {
    key = `#${escape(element.id)}`;
  } else {
    for (const { name, value } of Array.from(element.attributes)) {
      if (
        !/^data-(?:world|floor-note|dashboard)-/.test(name) ||
        WORLD_NOTICE_KEY_SKIP.has(name)
      ) {
        continue;
      }
      key =
        value && value.length <= 120
          ? `[${name}="${escape(value)}"]`
          : `[${name}]`;
      break;
    }
    if (!key && element.getAttribute("aria-labelledby")) {
      key = `[aria-labelledby="${escape(element.getAttribute("aria-labelledby"))}"]`;
    }
  }
  if (!key) return "";
  try {
    return document.querySelectorAll(key).length === 1 ? key : "";
  } catch (_) {
    return "";
  }
}

function worldNoticeVisible(element) {
  if (!(element instanceof Element) || !element.isConnected) return false;
  if (element.closest("[hidden], [aria-hidden='true'], [inert]")) return false;
  return element.checkVisibility?.({ visibilityProperty: true }) !== false;
}

function worldNoticeView(element) {
  return String(
    element?.closest?.("[data-open-landmark]")?.dataset.openLandmark || "",
  );
}

