    this.disabledWorldElements = storedDisabledWorldElements();
    // A package removed in Marketplace stays absent across reloads until the
    // visitor explicitly installs it again.
    this.removedWorldPackages = storedRemovedWorldPackages();
    // Opt-in packages the visitor installed here; they are off by default.
    this.installedWorldPackages = storedInstalledWorldPackages();
